window.COURSE={"title":"My Clinic — Facility Management & Safety","short_title":"Facility Management & Safety","prefix":"hs1","module":"01","colour":"#008C99","colour_ink":"#006E78","duration":55,"tracking":{"completion_rule":"viewed_all_and_passed","passing_score":80},"objectives":[{"id":"hs1-o1","description":"Name the eight FMS plans and match each to its purpose."},{"id":"hs1-o2","description":"Apply the AREC cycle and the hierarchy of controls to a workplace hazard."},{"id":"hs1-o3","description":"Match each MOH emergency code to its meaning and follow the common response pattern."},{"id":"hs1-o4","description":"Respond to a fire using RACE and PASS, choosing the correct extinguisher and evacuation type."},{"id":"hs1-o5","description":"Interpret GHS pictograms and the NFPA diamond, decide on Code Orange, and segregate waste correctly."},{"id":"hs1-o6","description":"Apply ID, visitor, contractor and premises security rules."},{"id":"hs1-o7","description":"Identify emergency power, utility shut-offs and HVAC rules in a clinical area."},{"id":"hs1-o8","description":"Take faulty or overdue medical equipment out of use and report it to Biomedical Engineering."},{"id":"hs1-o9","description":"Apply ALARA, dose-limit bands and laser classes to stay safe near radiation and lasers."},{"id":"hs1-o10","description":"Combine the plans in one connected emergency (capstone)."}],"variables":[{"name":"role","type":"text","default":"all"},{"name":"role_label","type":"text","default":"team member"},{"name":"xp","type":"number","default":0},{"name":"meter","type":"number","default":3},{"name":"hint","type":"number","default":0}],"points_var":"xp","levels":[{"name":"Newcomer","min_points":0},{"name":"Safety Spotter","min_points":88},{"name":"Safety Ally","min_points":177},{"name":"Safety Champion","min_points":251}],"lives_var":"meter","max_lives":5,"meter_label":"Clinic safety","titles":{"Welcome":"Welcome","1 · The eight FMS plans":"Mission 1 · The eight FMS plans","2 · Occupational Health & Safety":"Mission 2 · Occupational Health & Safety","3 · Emergency codes":"Mission 3 · Emergency codes","4 · Fire safety":"Mission 4 · Fire safety","5 · Hazardous materials & waste":"Mission 5 · Hazardous materials & waste","6 · Security":"Mission 6 · Security","7 · Utilities":"Mission 7 · Utilities","8 · Medical equipment":"Mission 8 · Medical equipment","9 · Radiation & laser":"Mission 9 · Radiation & laser","Capstone & completion":"Capstone & completion"},"assets":{"char-noor-welcome":"assets/char-noor-welcome.png","char-noor-explaining":"assets/char-noor-explaining.png","hs1-img-8plans":"assets/hs1-img-8plans.svg","hs1-img-arec":"assets/hs1-img-arec.svg","char-noor-avatar-neutral":"assets/char-noor-avatar-neutral.png","hs1-img-ert":"assets/hs1-img-ert.svg","hs1-img-triangle":"assets/hs1-img-triangle.svg","hs1-img-corridor":"assets/hs1-img-corridor.png","hs1-img-nfpa-blank":"assets/hs1-img-nfpa-blank.svg","hs1-img-eyewash":"assets/hs1-img-eyewash.jpg","char-noor-avatar-concern":"assets/char-noor-avatar-concern.png","hs1-img-treatment-room":"assets/hs1-img-treatment-room.jpg","hs1-img-pump-label":"assets/hs1-img-pump-label.jpg","char-omar-avatar-neutral":"assets/char-omar-avatar-neutral.png","hs1-img-alara":"assets/hs1-img-alara.svg","hs1-img-staffroom":"assets/hs1-img-staffroom.jpg","hs1-img-challenge":"assets/hs1-img-challenge.jpg","char-omar-explaining":"assets/char-omar-explaining.png","brand-logo-horizontal-navy":"assets/brand-logo-horizontal-navy.png","font-montserrat-400":"assets/montserrat-latin-400-normal.woff2","font-montserrat-600":"assets/montserrat-latin-600-normal.woff2","font-montserrat-700":"assets/montserrat-latin-700-normal.woff2"},"logo":"assets/brand-logo-horizontal-navy.png","petal":"assets/mark-white.png","screens":[{"type":"title_slide","id":"hs1-000","title":"Facility Management & Safety","section":"Welcome","objective_ids":[],"points":0,"subtitle":"Your first-week safety essentials","body_html":"<div class=\"mc-guides\"><div class=\"mc-guide noor\">{{asset:char-noor-welcome}}<span>Noor</span></div></div>"},{"type":"content_slide","id":"hs1-001","title":"Why it matters; how the course works","section":"Welcome","objective_ids":[],"points":0,"body_html":"<ul><li><strong>Protect patients</strong></li><li><strong>Protect you</strong></li><li><strong>Pass the CBAHI survey</strong></li></ul><p>9 short sections · resume any time</p>","layout":"text_media","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide."},{"type":"poll","id":"hs1-002","title":"How confident are you?","section":"Welcome","objective_ids":[],"points":0,"prompt_html":"<p>How confident are you to act in a fire right now?</p>","options":[{"id":"c1","text_html":"1 — Not confident yet"},{"id":"c2","text_html":"2 — A little confident"},{"id":"c3","text_html":"3 — Fairly confident"},{"id":"c4","text_html":"4 — Very confident"}],"multi":false,"allow_text":false,"reflection_html":"<p>Not scored. We'll come back to this at the end.</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"branching","id":"hs1-003","title":"Make it yours","prompt_html":"<p><strong>Which best describes your role?</strong></p><p>We'll add tips for your work. Every scored activity is the same for everyone.</p>","choices":[{"id":"clinical","text_html":"<strong>Clinical</strong><br><small>Physicians, dentists, nurses, lab, radiology, pharmacy, physiotherapy</small>","goto_screen_id":"hs1-00m","set_vars":[{"var":"role","op":"set","value":"clinical"},{"var":"role_label","op":"set","value":"clinician"}]},{"id":"front","text_html":"<strong>Front office & My Care</strong><br><small>Reception, call centre, patient experience, My Care coordinators</small>","goto_screen_id":"hs1-00m","set_vars":[{"var":"role","op":"set","value":"front"},{"var":"role_label","op":"set","value":"front-office colleague"}]},{"id":"support","text_html":"<strong>Support & back office</strong><br><small>Admin, HR, finance, RCM, IT, facilities, housekeeping, security</small>","goto_screen_id":"hs1-00m","set_vars":[{"var":"role","op":"set","value":"support"},{"var":"role_label","op":"set","value":"support colleague"}]},{"id":"all","text_html":"<strong>Show me every role's tips</strong>","goto_screen_id":"hs1-00m","set_vars":[{"var":"role","op":"set","value":"all"},{"var":"role_label","op":"set","value":"team member"}]}],"default_goto":"hs1-00m","points":0,"objective_ids":[],"section":"Welcome"},{"type":"content_slide","id":"hs1-00m","title":"First-week safety challenge","layout":"text_media","body_html":"<h3>Can you keep your clinic safe in your first week?</h3><p class=\"mc-missions\"><strong>9 missions:</strong> <strong>1</strong> The eight FMS plans · <strong>2</strong> Occupational Health & Safety · <strong>3</strong> Emergency codes · <strong>4</strong> Fire safety · <strong>5</strong> Hazardous materials & waste · <strong>6</strong> Security · <strong>7</strong> Utilities · <strong>8</strong> Medical equipment · <strong>9</strong> Radiation & laser</p><p class=\"mc-xp-rules\"><strong>Earn XP:</strong> +10 for each activity you get right · +5 for each quick check · +2 for each screen you explore. <strong>Ranks:</strong> Newcomer → Safety Spotter → Safety Ally → Safety Champion.</p><p><strong>Clinic safety</strong> (the dots at the top) goes up with each good decision and down with each risky one. Ask Noor or Dr. Omar for a hint before a big decision.</p><p class=\"mc-note\">XP is just for you: it never counts towards your pass mark.</p>","points":0,"objective_ids":[],"media_asset_id":"hs1-img-challenge","media_alt":"Illustration for the first-week safety challenge.","section":"Welcome"},{"type":"content_slide","id":"hs1-101","title":"Why the FMS chapter exists","section":"1 · The eight FMS plans","objective_ids":[],"points":0,"body_html":"<ul><li><strong>Survey requirement</strong> — surveyors check all eight plans: documents, staff knowledge, physical evidence.</li><li><strong>Everyone's responsibility</strong> — every employee knows their role.</li><li><strong>One connected system</strong> — plans and emergency codes overlap.</li></ul><p>CBAHI chapter wording ⚠ Draft — pending 01/B9</p>","layout":"text"},{"type":"hotspot","id":"hs1-102","title":"Explore the eight plans","section":"1 · The eight FMS plans","objective_ids":[],"points":0,"prompt_html":"<p>Open all eight plans. Each one protects against a different physical risk.</p>","image_asset_id":"hs1-img-8plans","image_alt":"Eight Facility Management and Safety plans shown as icons.","mode":"explore","require_all":true,"regions":[{"id":"fire","shape":"rect","coords":[0,0,240,270],"label_html":"<strong>Fire Safety Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Protect people from harm caused by fire and smoke.</p><p><strong>Main functions:</strong> Prevention and routine inspections · Detection and suppression systems · Code Red response (RACE/PASS) · Evacuation routes and drills</p>"},{"id":"building","shape":"rect","coords":[240,0,240,270],"label_html":"<strong>Building Safety Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Keep the physical environment free of hazards.</p><p><strong>Main functions:</strong> Environmental and safety rounds · Hazard identification and correction · Construction/renovation risk assessment · Safety signage and wayfinding</p>"},{"id":"hazmat","shape":"rect","coords":[480,0,240,270],"label_html":"<strong>Hazmat & Waste Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Safely manage chemicals and medical waste end to end.</p><p><strong>Main functions:</strong> Inventory, SDS and GHS/NFPA labelling · Safe storage, handling and transport · Code Orange spill response · Waste segregation and disposal</p>"},{"id":"utility","shape":"rect","coords":[720,0,240,270],"label_html":"<strong>Utility Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Keep essential utility systems running safely.</p><p><strong>Main functions:</strong> Critical system inventory · Preventive maintenance · Backup power and water continuity · Code Brown response</p>"},{"id":"biomed","shape":"rect","coords":[0,270,240,270],"label_html":"<strong>Biomedical Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Make sure medical equipment is safe and working.</p><p><strong>Main functions:</strong> Equipment inventory and inspection · Planned preventive maintenance (PPM) · Incident and recall management · User training</p>"},{"id":"security","shape":"rect","coords":[240,270,240,270],"label_html":"<strong>Security Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Protect people, property and information.</p><p><strong>Main functions:</strong> Access control and ID badges · Visitor and contractor management · CCTV monitoring · Response to Codes White, Silver, Black and Pink</p>"},{"id":"internal","shape":"rect","coords":[480,270,240,270],"label_html":"<strong>Internal Disaster Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Prepare for emergencies that start inside the facility.</p><p><strong>Main functions:</strong> Emergency code activation · Emergency Response Team (ERT) roles · Continuity of critical services · Regular internal drills</p>"},{"id":"external","shape":"rect","coords":[720,270,240,270],"label_html":"<strong>External Disaster Plan</strong>","feedback_html":"<p><strong>Purpose:</strong> Prepare for mass-casualty or community events.</p><p><strong>Main functions:</strong> Surge capacity planning · Coordination with Civil Defence, MOH and Red Crescent · Code Yellow triage and communication · Community drills</p>"}],"feedback":{"correct_html":"<p>You opened all eight plans. Each protects against a different physical risk; together they form one chapter.</p>","incorrect_html":"<p>Open every plan before you continue: each one covers a different physical risk.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"content_slide","id":"hs1-103","title":"Plans and codes: one system","section":"1 · The eight FMS plans","objective_ids":[],"points":0,"body_html":"<blockquote><strong>A fire is a Code Red. A chemical spill is a Code Orange.</strong></blockquote><p>The eight plans and the emergency codes are two views of the same system.</p>"},{"type":"matching","id":"hs1-104","title":"Match the plans","section":"1 · The eight FMS plans","objective_ids":["hs1-o1"],"points":10,"prompt_html":"<p>Match each plan to its purpose.</p>","pairs":[{"id":"fire","left_html":"Fire Safety Plan","right_html":"Protect people from harm caused by fire and smoke."},{"id":"building","left_html":"Building Safety Plan","right_html":"Keep the physical environment free of hazards."},{"id":"hazmat","left_html":"Hazmat & Waste Plan","right_html":"Safely manage chemicals and medical waste end to end."},{"id":"utility","left_html":"Utility Plan","right_html":"Keep essential utility systems running safely."},{"id":"biomed","left_html":"Biomedical Plan","right_html":"Make sure medical equipment is safe and working."},{"id":"security","left_html":"Security Plan","right_html":"Protect people, property and information."},{"id":"internal","left_html":"Internal Disaster Plan","right_html":"Prepare for emergencies that start inside the facility."},{"id":"external","left_html":"External Disaster Plan","right_html":"Prepare for mass-casualty or community events."}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Each plan covers one physical risk; together they protect patients, staff and visitors.</p>","incorrect_html":"<p>Not quite. Look for the risk each plan protects against: fire and smoke, the building, chemicals and waste, utilities, equipment, people and property, inside events or community events. The correct set is shown below.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"flashcards","id":"hs1-201","title":"Four core terms","section":"2 · Occupational Health & Safety","objective_ids":[],"points":0,"prompt_html":"<p>Flip each card: term on the front, meaning and an example on the back.</p>","cards":[{"front_html":"<h3>Health</h3>","back_html":"<p>Complete physical, mental and social well-being — not only the absence of injury or illness.</p>"},{"front_html":"<h3>Safety</h3>","back_html":"<p>Freedom from conditions that cause injury, illness or damage, achieved by controlling hazards <em>before</em> they cause harm.</p>"},{"front_html":"<h3>Hazard</h3>","back_html":"<p>Anything that could cause harm. <em>Example:</em> a wet floor, an unlabelled chemical, an exposed wire.</p>"},{"front_html":"<h3>Risk</h3>","back_html":"<p>How likely the hazard is to cause harm, combined with how severe that harm would be. <em>Example:</em> a wet floor near a busy waiting area.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hs1-202","title":"Incident types","section":"2 · Occupational Health & Safety","objective_ids":[],"points":0,"prompt_html":"<p>Open each incident type.</p>","items":[{"title":"Near miss — most valuable to report","body_html":"<p>Nothing happened, but it easily could have. Reporting it is free learning.</p>"},{"title":"First aid case","body_html":"<p>Minor injury treated with on-site first aid; no further medical care.</p>"},{"title":"Medical treatment case","body_html":"<p>Needs treatment beyond first aid, such as stitches or prescribed medication.</p>"},{"title":"Lost time injury","body_html":"<p>The employee cannot return to normal duties for a period.</p>"},{"title":"Fatality","body_html":"<p>Death from a workplace incident; triggers mandatory investigation and regulatory reporting.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"labeled_diagram","id":"hs1-203","title":"The AREC cycle","section":"2 · Occupational Health & Safety","objective_ids":[],"points":0,"prompt_html":"<p>AREC is a habit before every task. Hazard awareness is never a one-time task.</p>","image_asset_id":"hs1-img-arec","image_alt":"AREC cycle: Anticipate, Recognise, Evaluate, Control.","mode":"display","labels":[{"id":"a","text":"Anticipate — think ahead before the task","x":500,"y":200},{"id":"r","text":"Recognise — spot hazards as they appear","x":800,"y":511},{"id":"e","text":"Evaluate — how likely, how severe","x":500,"y":820},{"id":"c","text":"Control — use the hierarchy, top first","x":200,"y":511}],"feedback":{"correct_html":"<p>Anticipate, recognise, evaluate, control — then start again. Use it before every task.</p>","incorrect_html":"<p>Read each stage: the cycle repeats because hazards change.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"sorting","id":"hs1-204","title":"Hierarchy of controls","section":"2 · Occupational Health & Safety","objective_ids":["hs1-o2"],"points":10,"prompt_html":"<p>Put the controls in order, from most to least effective.</p>","items":[{"id":"elim","text_html":"<strong>Elimination</strong> — physically remove the hazard"},{"id":"subs","text_html":"<strong>Substitution</strong> — replace it with something safer"},{"id":"eng","text_html":"<strong>Engineering controls</strong> — isolate people from the hazard"},{"id":"admin","text_html":"<strong>Administrative controls</strong> — change how people work"},{"id":"ppe","text_html":"<strong>PPE</strong> — protect the individual worker"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Start at the top: the higher a control sits, the more reliably it removes the risk. PPE is the last line of defence, not the first.</p>","incorrect_html":"<p>Not quite. Removing or replacing the hazard protects everyone; PPE only protects the person wearing it. PPE is the last line of defence, not the first.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"section":"2 · Occupational Health & Safety","points":0,"objective_ids":[],"type":"branching","id":"hs1-205-ask","title":"The trailing cable","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Noor first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Noor</strong>","goto_screen_id":"hs1-205-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hs1-205","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hs1-205"},{"section":"2 · Occupational Health & Safety","points":0,"objective_ids":[],"type":"content_slide","id":"hs1-205-hint","title":"Noor's hint","layout":"text_media","body_html":"<p><strong>Noor:</strong> “Think about who could get hurt in the next minute, and which fix removes the hazard rather than just warning about it. You may always stop unsafe work.”</p>","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hs1-205","title":"The trailing cable","section":"2 · Occupational Health & Safety","objective_ids":["hs1-o2"],"points":15,"intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-neutral}}<span>Noor · Safety liaison</span></div><p>A power cable trails across the walkway beside the patient waiting area. Patients and visitors are walking past.</p>","start_node_id":"n1","pass_score":2,"nodes":[{"id":"n1","prompt_html":"<p>You spot the cable. What do you do first?</p>","choices":[{"id":"a","text_html":"Stop, warn people nearby and keep them clear while you assess the risk.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Best choice.</strong> You recognised the hazard and protected people first. Now evaluate it and choose a control.</p>"},{"id":"b","text_html":"Step over it and carry on; someone else will report it.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Not safe. A trip hazard beside patients is everyone's responsibility. Recognising it and doing nothing leaves the risk in place.</p>"},{"id":"c","text_html":"Go and complete an incident form before doing anything else.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Reporting matters, but not before people are protected. Someone could trip while you are away.</p>"}]},{"id":"n2","prompt_html":"<p>Which control is strongest?</p>","choices":[{"id":"a","text_html":"Re-route the cable away from the walkway.","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Strongest.</strong> Removing the hazard from the walkway sits at the top of the hierarchy — nobody can trip on it.</p>"},{"id":"b","text_html":"Cover the cable with a cable protector.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Better than a sign, but the cable is still in the walkway. Removing it from the path is stronger.</p>"},{"id":"c","text_html":"Put up a warning sign.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>A sign is an administrative control. It relies on people noticing it, so it is weaker than removing the hazard.</p>"},{"id":"d","text_html":"Warn each person who walks past.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Warning people is the weakest option here. It depends on you being there every time.</p>"}]},{"id":"n3","prompt_html":"<p>Your supervisor says: “Leave it, we're busy.” What do you do?</p>","choices":[{"id":"a","text_html":"Use your right to stop unsafe work and contact your Department Safety Liaison.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Under ISO 45001 you can stop work you believe could cause serious harm, without fear of retaliation. Your Safety Liaison is the bridge to EHS.</p>"},{"id":"b","text_html":"Leave it; the supervisor has decided.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>The hazard is still there. Your rights exist so that safety concerns are never silenced by fear of consequences.</p>"},{"id":"c","text_html":"Ignore the supervisor and argue in front of patients.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>The concern is valid, but raise it through the right route: stop the unsafe work and contact your Safety Liaison or Safety Officer.</p>"}]}],"feedback":{"correct_html":"<p>You put people first, chose the strongest control and used your rights.</p>","incorrect_html":"<p>Review AREC and the hierarchy of controls, then try again. People first; remove the hazard if you can; you may stop unsafe work.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"accordion","id":"hs1-206","title":"Who to contact and your rights","section":"2 · Occupational Health & Safety","objective_ids":[],"points":0,"prompt_html":"<p>Who to contact, and your rights under ISO 45001.</p>","items":[{"title":"Department Safety Liaison","body_html":"<p>Your first contact for hazards, risk assessments and PPE questions. Don't know yours? Ask your supervisor on day 1.</p>"},{"title":"Right to stop unsafe work","body_html":"<p>Stop any task you believe could cause serious harm, without fear of retaliation.</p>"},{"title":"Right to be consulted","body_html":"<p>If you are afraid to stop work yourself, raise the concern with your Safety Officer or supervisor.</p>"},{"title":"Right to training","body_html":"<p>Be trained on the hazards and safe procedures of your role <em>before</em> you do it.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"flashcards","id":"hs1-301","title":"The emergency codes","section":"3 · Emergency codes","objective_ids":[],"points":0,"prompt_html":"<p>Flip each card. Codes are announced overhead. Code names and site extensions ⚠ Draft — pending D2.</p>","cards":[{"front_html":"<h3>Code Red</h3>","back_html":"<p>Fire</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Orange</h3>","back_html":"<p>Hazardous material spillage</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code White</h3>","back_html":"<p>Violent situation</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Black</h3>","back_html":"<p>Bomb threat</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Pink</h3>","back_html":"<p>Child / infant abduction or lost</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Blue</h3>","back_html":"<p>Cardiac arrest</p><p><strong>Extension:</strong> 2222 — national (MOH)</p>"},{"front_html":"<h3>Code RRT</h3>","back_html":"<p>Deteriorating patient (Rapid Response Team)</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Silver</h3>","back_html":"<p>Violent situation involving a weapon</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Yellow</h3>","back_html":"<p>External disaster</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Grey</h3>","back_html":"<p>Severe weather</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"},{"front_html":"<h3>Code Brown</h3>","back_html":"<p>Utility failure</p><p><strong>Extension:</strong> your site number ⚠ Draft — pending D2</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"matching","id":"hs1-302","title":"Match the codes","section":"3 · Emergency codes","objective_ids":["hs1-o3"],"points":10,"prompt_html":"<p>Match each code to its meaning. Code naming ⚠ Draft — pending D2.</p>","pairs":[{"id":"red","left_html":"Code Red","right_html":"Fire"},{"id":"orange","left_html":"Code Orange","right_html":"Hazardous material spill"},{"id":"white","left_html":"Code White","right_html":"Violent situation"},{"id":"black","left_html":"Code Black","right_html":"Bomb threat"},{"id":"pink","left_html":"Code Pink","right_html":"Child / infant abduction"},{"id":"blue","left_html":"Code Blue","right_html":"Cardiac arrest"},{"id":"yellow","left_html":"Code Yellow","right_html":"External disaster"},{"id":"brown","left_html":"Code Brown","right_html":"Utility failure"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Knowing the meaning lets you act the moment a code is announced. Check your site's extensions too.</p>","incorrect_html":"<p>Not quite. Review the code cards: Red is fire, Orange is a hazardous spill, Blue is cardiac arrest. The correct set is shown below. ⚠ Draft — pending D2</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hs1-303","title":"Two announcements","section":"3 · Emergency codes","objective_ids":[],"points":0,"blocks":[{"html":"<p>Two facility-wide announcements are not colour codes:</p>"},{"html":"<h4>Hospital Evacuation</h4><p>Evacuate the building. Follow your unit's evacuation plan to the outdoor assembly point.</p>"},{"html":"<h4>End of Disaster</h4><p>The Incident Commander confirms the emergency is over. Stand down only on this signal.</p>"}]},{"type":"true_false","id":"hs1-303c","title":"Check: after the fire","prompt_html":"<p><strong>Quick check (not scored).</strong> The fire is out, so staff can go back to their rooms.</p>","correct":false,"feedback":{"correct_html":"<p>Right — it's false. Stand down only when the Incident Commander gives the <strong>End of Disaster</strong> announcement.</p>","incorrect_html":"<p>Not yet. A fire being out is not the signal. Wait for the <strong>End of Disaster</strong> announcement from the Incident Commander.</p>","show_correct_answer":true},"section":"3 · Emergency codes","points":0,"objective_ids":[],"on_correct":[{"var":"xp","op":"add","value":5}]},{"type":"sorting","id":"hs1-304","title":"The common response pattern","section":"3 · Emergency codes","objective_ids":["hs1-o3"],"points":5,"prompt_html":"<p>Put the common response pattern in order. It applies to every code.</p>","items":[{"id":"rec","text_html":"<strong>Recognise</strong> — notice the emergency as it develops"},{"id":"act","text_html":"<strong>Activate</strong> — call switchboard/security; announce the correct code"},{"id":"resp","text_html":"<strong>Respond</strong> — follow your role-specific response"},{"id":"stand","text_html":"<strong>Stand down</strong> — wait for the official all-clear"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> And remember: stand down only when the official all-clear is announced.</p>","incorrect_html":"<p>Not quite. You must recognise it before you can activate a code, and you resume normal work only after the official all-clear.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"labeled_diagram","id":"hs1-305","title":"Who responds: the ERT","section":"3 · Emergency codes","objective_ids":[],"points":0,"prompt_html":"<p>The Emergency Response Team: five teams around an Incident Commander. You are part of the response even if you are not on it.</p>","image_asset_id":"hs1-img-ert","image_alt":"Emergency Response Team: Safety, Security, Nursing, Facility, Operation around an Incident Commander.","mode":"display","labels":[{"id":"ic","text":"Incident Commander","x":500,"y":560},{"id":"safety","text":"Safety","x":500,"y":120},{"id":"security","text":"Security","x":820,"y":400},{"id":"nursing","text":"Nursing","x":700,"y":840},{"id":"facility","text":"Facility","x":300,"y":840},{"id":"operation","text":"Operation","x":180,"y":400}],"feedback":{"correct_html":"<p>Five teams work around one Incident Commander. Your part is to follow your role-specific response.</p>","incorrect_html":"<p>Read each team label: the Incident Commander coordinates them all.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"labeled_diagram","id":"hs1-401","title":"The fire triangle","section":"4 · Fire safety","objective_ids":[],"points":0,"prompt_html":"<p>Remove any one side and the fire stops. <strong>Smoke, not flame, is the leading cause of death</strong> in facility fires.</p>","image_asset_id":"hs1-img-triangle","image_alt":"Fire triangle: heat, fuel and oxygen.","mode":"display","labels":[{"id":"heat","text":"Heat — the ignition source","x":500,"y":170},{"id":"fuel","text":"Fuel — anything that burns","x":220,"y":860},{"id":"oxygen","text":"Oxygen — keeps it burning","x":780,"y":860}],"feedback":{"correct_html":"<p>Remove heat, fuel or oxygen and the fire stops. Smoke kills first, so RACE rescues and contains before extinguishing.</p>","incorrect_html":"<p>Read each side of the triangle: every fire control method removes one of them.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"sorting","id":"hs1-402","title":"RACE: put the steps in order","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":5,"prompt_html":"<p>You discover a fire. Put the response in the right order.</p>","items":[{"id":"r","text_html":"<strong>Rescue</strong> anyone in immediate danger"},{"id":"a","text_html":"<strong>Alarm</strong> — pull station + call: code, location, your ID and name"},{"id":"c","text_html":"<strong>Contain</strong> — remove O₂ and alcohol rub, close doors"},{"id":"e","text_html":"<strong>Extinguish</strong> a small fire, or <strong>Evacuate</strong>"}],"feedback":{"correct_html":"<p><strong>Right.</strong> Smoke spreads faster than flame, so people and doors come first.</p>","incorrect_html":"<p>Not quite. Rescue and contain come before extinguishing because smoke kills first.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"sorting","id":"hs1-403","title":"PASS: put the steps in order","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":5,"prompt_html":"<p>Using an extinguisher: put the PASS steps in order.</p>","items":[{"id":"p","text_html":"<strong>Pull</strong> the safety pin"},{"id":"a","text_html":"<strong>Aim</strong> low, at the base of the fire"},{"id":"s","text_html":"<strong>Squeeze</strong> the handle"},{"id":"w","text_html":"<strong>Sweep</strong> side to side until it is out"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Aim at the base: that is where the fuel is burning. Use an extinguisher only on a small, contained fire.</p>","incorrect_html":"<p>Not quite. The pin must come out before the handle works, and you aim at the base before you squeeze and sweep.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"hotspot","id":"hs1-404","title":"Find the fire safety equipment","section":"4 · Fire safety","objective_ids":[],"points":0,"prompt_html":"<p>Open every item. Know where these are before you need them.</p>","image_asset_id":"hs1-img-corridor","image_alt":"Clinic corridor showing a smoke detector, heat detector, sprinkler, call point, extinguisher, fire blanket, evacuation chair and assembly-point sign.","mode":"explore","require_all":true,"regions":[{"id":"smoke","shape":"rect","coords":[535,30,120,75],"label_html":"<strong>Smoke detector</strong>","feedback_html":"<p>Senses smoke early and triggers the alarm. Never cover or tamper with it.</p>"},{"id":"heat","shape":"rect","coords":[968,30,118,75],"label_html":"<strong>Heat detector</strong>","feedback_html":"<p>Triggers the alarm when the temperature rises fast — used where smoke detectors would false-alarm.</p>"},{"id":"sprinkler","shape":"rect","coords":[782,122,72,64],"label_html":"<strong>Sprinkler</strong>","feedback_html":"<p>Releases water automatically over a fire. Keep the space below it clear; never hang anything from it.</p>"},{"id":"callpoint","shape":"rect","coords":[92,252,102,112],"label_html":"<strong>Call point</strong>","feedback_html":"<p>Manual alarm. Pull it during the <strong>Alarm</strong> step of RACE.</p>"},{"id":"extinguisher","shape":"rect","coords":[68,476,148,308],"label_html":"<strong>Fire extinguisher</strong>","feedback_html":"<p>For a small, contained fire only. Check the class label, then use PASS.</p>"},{"id":"blanket","shape":"rect","coords":[1498,312,122,240],"label_html":"<strong>Fire blanket</strong>","feedback_html":"<p>Smothers a small fire, such as a pan or clothing fire, by cutting off oxygen.</p>"},{"id":"evacchair","shape":"rect","coords":[1040,534,224,304],"label_html":"<strong>Evacuation chair</strong>","feedback_html":"<p>Moves a person who cannot walk down the stairs during a vertical evacuation. Never use the elevator.</p>"},{"id":"assembly","shape":"rect","coords":[1070,278,88,106],"label_html":"<strong>Assembly-point sign</strong>","feedback_html":"<p>Shows the route to the outdoor assembly point used in a full evacuation. Find yours this week.</p>"},{"id":"stairs","shape":"rect","coords":[1335,520,160,240],"label_html":"<strong>Stairwell exit</strong>","feedback_html":"<p>Your way out in a fire. Use the stairs, never the lift, and keep this door and the corridor clear. <em>(Proposed — SME to confirm at review.)</em></p>"}],"feedback":{"correct_html":"<p>You found all eight items. Look for them on your own unit this week.</p>","incorrect_html":"<p>Open every item before you continue: you need to know where each one is before an emergency.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"drag_drop","id":"hs1-405","title":"Extinguisher classes","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":10,"prompt_html":"<p>Drag each fire to the extinguisher class that fits. Using the wrong class can make a fire worse.</p>","items":[{"id":"paper","text_html":"Burning paper bin","correct_target_id":"a"},{"id":"petrol","text_html":"Petrol leak","correct_target_id":"b"},{"id":"copier","text_html":"Smoking photocopier","correct_target_id":"c"},{"id":"magnesium","text_html":"Magnesium shavings","correct_target_id":"d"},{"id":"pan","text_html":"Pantry pan fire","correct_target_id":"k"}],"targets":[{"id":"a","label_html":"Class A — wood, paper, fabric, trash"},{"id":"b","label_html":"Class B — flammable liquids and gases"},{"id":"c","label_html":"Class C — energised electrical equipment"},{"id":"d","label_html":"Class D — combustible metals"},{"id":"k","label_html":"Class K — cooking oils and fats"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Check the label before you pull the pin.</p>","incorrect_html":"<p>Not quite. Match the fuel: ordinary materials A, liquids B, live electrical C, metals D, cooking oil K. Check the label before you pull the pin.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"tabs","id":"hs1-406","title":"Types of evacuation","section":"4 · Fire safety","objective_ids":[],"points":0,"prompt_html":"<p>Three types of evacuation.</p>","tabs":[{"label":"Horizontal","body_html":"<p>Move patients and staff through fire/smoke doors to the next safe compartment on the <strong>same floor</strong>. The first response for most fires.</p>"},{"label":"Vertical","body_html":"<p>Move to a lower floor or ground level when horizontal is not enough. Use <strong>stairwells, never elevators</strong>.</p>"},{"label":"Full","body_html":"<p>Evacuate the whole building to the <strong>outdoor assembly point</strong>. Only for the most severe, facility-wide emergencies.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hs1-407","title":"Choose the evacuation","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":5,"prompt_html":"<p>Smoke is coming from Room 3. Fire doors are at the end of the corridor. Patients on the same floor are not in danger yet. What is your first move?</p>","options":[{"id":"a","text_html":"Move patients horizontally through the fire doors to the next compartment.","correct":true,"feedback_html":"<p>Correct. Horizontal evacuation is the first response for most fires: the fire doors hold back smoke.</p>"},{"id":"b","text_html":"Take patients down to the ground floor in the elevator.","correct":false,"feedback_html":"<p>Never use elevators in a fire. They can fail or open onto the fire floor; vertical moves use the stairwells.</p>"},{"id":"c","text_html":"Start a full evacuation of the building to the assembly point.","correct":false,"feedback_html":"<p>Too early. Full evacuation is for the most severe, facility-wide emergencies; moving patients beyond the fire doors is enough now.</p>"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Horizontal first; vertical by the stairs only if needed.</p>","incorrect_html":"<p>Not quite. The patients are not in danger yet, and fire doors are close: move them horizontally to the next compartment.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"true_false","id":"hs1-408","title":"Oxygen: myth or fact?","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":5,"prompt_html":"<p>True or false? <strong>Oxygen is flammable.</strong></p>","correct":false,"feedback":{"correct_html":"<p><strong>Correct — it is false.</strong> Oxygen is an oxidiser. It does not burn on its own, but it makes a fire burn much faster and hotter. Keep cylinders away from flames and sparks.</p>","incorrect_html":"<p>Not quite. Oxygen does not burn; it is an oxidiser that intensifies fire. That is why you remove oxygen cylinders when you contain a fire.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"section":"4 · Fire safety","points":0,"objective_ids":[],"type":"branching","id":"hs1-409-ask","title":"Night shift: put RACE into action","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Noor first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Noor</strong>","goto_screen_id":"hs1-409-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hs1-409","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hs1-409"},{"section":"4 · Fire safety","points":0,"objective_ids":[],"type":"content_slide","id":"hs1-409-hint","title":"Noor's hint","layout":"text_media","body_html":"<p><strong>Noor:</strong> “Remember the order in RACE: people first, then the alarm, then containing the fire. An alarm call needs three things: the code, where you are, and who you are.”</p>","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hs1-409","title":"Night shift: put RACE into action","section":"4 · Fire safety","objective_ids":["hs1-o4"],"points":20,"intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-neutral}}<span>Noor · Safety liaison</span></div><p>Night shift. Smoke is rising from a waste bin in a patient room. The patient is in bed beside it.</p>","start_node_id":"n1","pass_score":3,"nodes":[{"id":"n1","prompt_html":"<p>What do you do first?</p>","choices":[{"id":"a","text_html":"Move the patient away from the bin and out of the room.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Rescue first.</strong> The patient is safe from the smoke before anything else happens.</p>"},{"id":"b","text_html":"Fetch the extinguisher from the corridor.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>The patient stayed in the smoke while you were away. Smoke kills first, so rescue comes before extinguishing.</p>"},{"id":"c","text_html":"Run to the nurses' station to phone switchboard.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>The alarm matters, but the patient was left beside the fire. Rescue anyone in immediate danger first.</p>"}]},{"id":"n2","prompt_html":"<p>You pull the call point and phone switchboard. What do you say?</p>","choices":[{"id":"a","text_html":"“Code Red, Ward 2, Room 12. My ID is 4417, my name is Sara.”","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Code type, exact location, your ID and name — the team can come straight to you.</p>"},{"id":"b","text_html":"“There's a fire, come quickly!”","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Without the code and location the team loses time finding you. Always state code, location, ID and name.</p>"},{"id":"c","text_html":"“Code Orange in Room 12.”","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Code Orange is a hazardous spill. A fire is Code Red; the wrong code sends the wrong team.</p>"}]},{"id":"n3","prompt_html":"<p>The patient is safe and the alarm is raised. How do you contain the fire?</p>","choices":[{"id":"a","text_html":"Remove the oxygen cylinder and alcohol rub, then close the door.","score_delta":1,"goto_node_id":"n4","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Removing oxidisers and flammables and closing the door slows the smoke and fire.</p>"},{"id":"b","text_html":"Open the window to let the smoke out.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Opening a window feeds the fire with oxygen. Close doors and windows to contain it.</p>"},{"id":"c","text_html":"Leave the door open so the team can find the room.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>An open door lets smoke spread down the corridor. You gave the location on the call; close the door.</p>"}]},{"id":"n4","prompt_html":"<p>The fire spreads past the bin. Smoke reaches the corridor. What now?</p>","choices":[{"id":"a","text_html":"Evacuate patients horizontally through the fire doors to the next compartment.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> The fire is no longer small and contained, so you evacuate. Horizontal is the first move.</p>"},{"id":"b","text_html":"Keep fighting it with the extinguisher.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>An extinguisher is only for a small, contained fire. Once it grows, evacuate.</p>"},{"id":"c","text_html":"Take patients down in the elevator.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Never use elevators in a fire. Move horizontally first; use the stairwells if you must go down.</p>"}]}],"feedback":{"correct_html":"<p>You followed RACE under pressure: rescue, alarm, contain, then evacuate.</p>","incorrect_html":"<p>Review RACE and the evacuation types, then try again. People and doors come first; evacuate once the fire grows.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"hotspot","title":"Fire prevention: what not to bring","prompt_html":"<p>Find all seven things that should not be in this staff room.</p>","image_asset_id":"hs1-img-staffroom","image_alt":"Staff room with seven fire hazards: a candle, a home extension lead, a fan heater, a vape, a microwave, an open flammable bottle and welding kit by the door.","mode":"explore","require_all":true,"regions":[{"id":"candle","shape":"rect","coords":[400,458,92,152],"label_html":"<strong>Candle or open flame</strong>","feedback_html":"<p>Open flame is banned everywhere in the clinic.</p>"},{"id":"extension","shape":"rect","coords":[620,866,230,112],"label_html":"<strong>Home extension lead</strong>","feedback_html":"<p>Only Facilities-approved extensions; daisy-chained leads overheat.</p>"},{"id":"heater","shape":"rect","coords":[914,784,182,196],"label_html":"<strong>Fan heater</strong>","feedback_html":"<p>Personal heaters and electric boilers are not allowed.</p>"},{"id":"vape","shape":"rect","coords":[306,440,92,172],"label_html":"<strong>Vape or cigarette</strong>","feedback_html":"<p>No smoking or vaping indoors.</p>"},{"id":"microwave","shape":"rect","coords":[976,372,316,152],"label_html":"<strong>Unauthorised microwave</strong>","feedback_html":"<p>Only approved kitchen appliances, in approved places.</p>"},{"id":"flammable","shape":"rect","coords":[1288,392,88,144],"label_html":"<strong>Open flammable bottle</strong>","feedback_html":"<p>Flammables stay closed, labelled and in the approved cabinet.</p>"},{"id":"welding","shape":"rect","coords":[1336,606,172,250],"label_html":"<strong>Welding kit by a door</strong>","feedback_html":"<p>Hot work only with a Facilities permit.</p>"}],"feedback":{"correct_html":"<p><strong>All seven found.</strong> Flame and fuel, unsafe electrics and blocked exits start most clinic fires. If you see one at work, remove it or report it.</p>","incorrect_html":"<p>Keep looking: there are seven things in this room that should not be there.</p>","show_correct_answer":true},"id":"hs1-410","section":"4 · Fire safety","points":0,"objective_ids":[],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hs1-411-clinical","title":"Your part in a Code Red","prompt_html":"<p><strong>For your role.</strong> What you do first depends on where you work.</p>","items":[{"title":"Rescue","body_html":"<p>Move patients in your area away from smoke first: the ones who can walk, then those who need help. <em>Proposed — SME to confirm.</em></p>"},{"title":"Evacuation tools","body_html":"<p>Use the evacuation chair or sheet as you were trained; never the lift.</p>"}],"visible_if":{"var":"role","cmp":"==","value":"clinical"},"points":0,"objective_ids":[],"section":"4 · Fire safety","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hs1-411-front","title":"Your part in a Code Red","prompt_html":"<p><strong>For your role.</strong> What you do first depends on where you work.</p>","items":[{"title":"Stop arrivals","body_html":"<p>Stop new patients and visitors entering the affected area and guide those waiting to the assembly point. <em>Proposed — SME to confirm.</em></p>"},{"title":"Count heads","body_html":"<p>Keep the day's appointment list at hand so the team can check no one is left inside.</p>"}],"visible_if":{"var":"role","cmp":"==","value":"front"},"points":0,"objective_ids":[],"section":"4 · Fire safety","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hs1-411-support","title":"Your part in a Code Red","prompt_html":"<p><strong>For your role.</strong> What you do first depends on where you work.</p>","items":[{"title":"Clear the route","body_html":"<p>Keep corridors and fire doors clear; never block a door open. <em>Proposed — SME to confirm.</em></p>"},{"title":"Isolate as directed","body_html":"<p>Facilities isolate gas, oxygen or power only when the Incident Commander asks.</p>"}],"visible_if":{"var":"role","cmp":"==","value":"support"},"points":0,"objective_ids":[],"section":"4 · Fire safety","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"tabs","id":"hs1-411-all","title":"Your part in a Code Red","prompt_html":"<p>What you do first depends on where you work. Pick a role to compare.</p>","tabs":[{"label":"Clinical","body_html":"<h4>Rescue</h4><p>Move patients in your area away from smoke first: the ones who can walk, then those who need help. <em>Proposed — SME to confirm.</em></p><h4>Evacuation tools</h4><p>Use the evacuation chair or sheet as you were trained; never the lift.</p>"},{"label":"Front office & My Care","body_html":"<h4>Stop arrivals</h4><p>Stop new patients and visitors entering the affected area and guide those waiting to the assembly point. <em>Proposed — SME to confirm.</em></p><h4>Count heads</h4><p>Keep the day's appointment list at hand so the team can check no one is left inside.</p>"},{"label":"Support & back office","body_html":"<h4>Clear the route</h4><p>Keep corridors and fire doors clear; never block a door open. <em>Proposed — SME to confirm.</em></p><h4>Isolate as directed</h4><p>Facilities isolate gas, oxygen or power only when the Incident Commander asks.</p>"}],"visible_if":{"var":"role","cmp":"==","value":"all"},"points":0,"objective_ids":[],"section":"4 · Fire safety","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"content_slide","id":"hs1-501","title":"Ordering and inventory","section":"5 · Hazardous materials & waste","objective_ids":[],"points":0,"blocks":[{"html":"<h4>Approved procurement only</h4><p>No personal or unlogged purchases of hazardous substances.</p>"},{"html":"<h4>On the inventory, with its SDS</h4><p>Every chemical in your department is listed, and its Safety Data Sheet is easy to reach.</p>"},{"html":"<h4>Never accept an unlabelled container</h4><p>GHS pictograms show the hazard class at a glance.</p>"}]},{"type":"mcq","id":"hs1-501c","title":"Check: the unlabelled bottle","prompt_html":"<p><strong>Quick check (not scored).</strong> A courier hands you a bottle with no label and says it is the new disinfectant. What do you do?</p>","feedback":{"correct_html":"<p>Never accept an unlabelled container.</p>","incorrect_html":"<p>Never accept an unlabelled container: refuse it and route it through procurement.</p>","show_correct_answer":true},"options":[{"id":"o0","text_html":"Accept it and add a label yourself","correct":false,"feedback_html":"<p>A label you write is a guess. Without the supplier label and SDS, nobody knows the hazard.</p>"},{"id":"o1","text_html":"Refuse it and send it back through procurement","correct":true,"feedback_html":"<p>Right: approved procurement only, on the inventory, with its SDS.</p>"},{"id":"o2","text_html":"Put it in the store room until someone asks","correct":false,"feedback_html":"<p>An unknown chemical in storage is a hazard for the next person.</p>"}],"section":"5 · Hazardous materials & waste","points":0,"objective_ids":[],"on_correct":[{"var":"xp","op":"add","value":5}]},{"type":"drag_drop","id":"hs1-501s","title":"Put it where it belongs","prompt_html":"<p><strong>Practice (not scored).</strong> Drag each item to where it is stored or thrown away.</p>","targets":[{"id":"flam","label_html":"Flammables cabinet"},{"id":"sharps","label_html":"Sharps container"},{"id":"infect","label_html":"Infectious waste"},{"id":"general","label_html":"General waste"}],"items":[{"id":"i0","text_html":"Alcohol hand-rub refill","correct_target_id":"flam"},{"id":"i1","text_html":"Used needle","correct_target_id":"sharps"},{"id":"i2","text_html":"Blood-soaked gauze","correct_target_id":"infect"},{"id":"i3","text_html":"Empty paper packaging","correct_target_id":"general"},{"id":"i4","text_html":"Used scalpel blade","correct_target_id":"sharps"}],"feedback":{"correct_html":"<p>All in the right place. Flammables live in the approved cabinet, anything sharp goes in the sharps container, and anything soiled with body fluids is infectious waste.</p>","incorrect_html":"<p>Not yet. Sharp items always go in the sharps container; anything with blood or body fluids is infectious waste. Bin colours follow your facility poster. ⚠ Draft — pending 01/B7.</p>","show_correct_answer":true},"section":"5 · Hazardous materials & waste","points":0,"objective_ids":[],"on_correct":[{"var":"xp","op":"add","value":5}]},{"type":"matching","id":"hs1-502","title":"GHS pictograms","section":"5 · Hazardous materials & waste","objective_ids":["hs1-o5"],"points":10,"prompt_html":"<p>Match each GHS pictogram to the hazard it shows. (Red diamond, black symbol.)</p>","pairs":[{"id":"skull","left_html":"<strong>Skull and crossbones</strong>","right_html":"Acute toxicity"},{"id":"bomb","left_html":"<strong>Exploding bomb</strong>","right_html":"Explosives"},{"id":"corrosion","left_html":"<strong>Corrosion</strong>","right_html":"Skin and eye damage"},{"id":"flame","left_html":"<strong>Flame</strong>","right_html":"Flammable"},{"id":"exclaim","left_html":"<strong>Exclamation mark</strong>","right_html":"Irritant"},{"id":"health","left_html":"<strong>Health hazard</strong>","right_html":"Carcinogen / toxicity"},{"id":"cylinder","left_html":"<strong>Gas cylinder</strong>","right_html":"Gases under pressure"},{"id":"flamecircle","left_html":"<strong>Flame over circle</strong>","right_html":"Oxidisers"},{"id":"environment","left_html":"<strong>Environment</strong>","right_html":"Aquatic toxicity"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Read the pictogram before you open, mix or store a chemical, and check the SDS for details.</p>","incorrect_html":"<p>Not quite. The symbol shows the hazard: flame over circle is an oxidiser, the gas cylinder is pressure, the health hazard silhouette is carcinogen/toxicity. The correct set is shown below.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"labeled_diagram","id":"hs1-503","title":"Label the NFPA diamond","section":"5 · Hazardous materials & waste","objective_ids":["hs1-o5"],"points":10,"prompt_html":"<p>Label the four areas of the NFPA 704 diamond. Each area rates a hazard from 0 (minimal) to 4 (severe).</p>","image_asset_id":"hs1-img-nfpa-blank","image_alt":"Empty NFPA hazard diamond with four coloured quadrants.","mode":"quiz","labels":[{"id":"health","text":"Health (blue)","x":406,"y":522},{"id":"flam","text":"Flammability (red)","x":500,"y":356},{"id":"react","text":"Reactivity (yellow)","x":594,"y":522},{"id":"special","text":"Special (white)","x":500,"y":689}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Blue is health, red is flammability, yellow is reactivity and white holds special symbols such as W (avoid water) or OX (oxidiser).</p>","incorrect_html":"<p>Not quite. Use colour and the label together: blue health, red flammability, yellow reactivity, white special.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"mcq","id":"hs1-504","title":"Read a diamond","section":"5 · Hazardous materials & waste","objective_ids":["hs1-o5"],"points":5,"prompt_html":"<p>A container's diamond shows <strong>Health 3 · Flammability 0 · Reactivity 1 · Special W</strong>. What does it tell you before opening?</p>","options":[{"id":"a","text_html":"Serious health hazard; do not use water on it.","correct":true,"feedback_html":"<p>Correct. Health 3 is a serious hazard; W in the white area means avoid water.</p>"},{"id":"b","text_html":"Highly flammable; keep it away from heat.","correct":false,"feedback_html":"<p>Flammability is 0: it will not burn. The high number is health.</p>"},{"id":"c","text_html":"Low hazard overall; handle as normal.","correct":false,"feedback_html":"<p>Health 3 is serious. Check the SDS and wear the PPE it specifies.</p>"},{"id":"d","text_html":"Unstable and may explode; do not move it.","correct":false,"feedback_html":"<p>Reactivity 1 is low. The main risks are health and contact with water.</p>"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Read the whole diamond: the highest number and the white area tell you the main precautions.</p>","incorrect_html":"<p>Not quite. Higher numbers mean greater hazard. Here health is 3 and the white area says W: avoid water.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"accordion","id":"hs1-505","title":"Store, handle, transport","section":"5 · Hazardous materials & waste","objective_ids":[],"points":0,"prompt_html":"<p>Everything follows the Safety Data Sheet (SDS).</p>","items":[{"title":"Storage per SDS","body_html":"<p>Away from incompatible substances, secured, away from heat sources.</p>"},{"title":"Designated carts and routes","body_html":"<p>Never carry incompatible chemicals together; secure containers before moving them.</p>"},{"title":"PPE per SDS","body_html":"<p>Wear the PPE the SDS specifies before opening, mixing or dispensing.</p>"},{"title":"Flammable cabinet","body_html":"<p>Double-walled steel with a self-latching door. Flammable liquids never go on an open shelf.</p>"},{"title":"SDS at point of use","body_html":"<p>An SDS pocket or binder at or near the cabinet — every SDS reachable in seconds.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"content_slide","id":"hs1-506","title":"Eyewash and emergency showers","section":"5 · Hazardous materials & waste","objective_ids":[],"points":0,"body_html":"<p><strong>Find your nearest one today</strong> — not during an emergency.</p><p>Chemical in the eyes or on the skin: <strong>flush for at least 15 minutes</strong>, without stopping, then get a medical check.</p>","layout":"text_media","media_asset_id":"hs1-img-eyewash","media_alt":"Combined eyewash and emergency shower station."},{"section":"5 · Hazardous materials & waste","points":0,"objective_ids":[],"type":"branching","id":"hs1-507-ask","title":"Spill or Code Orange?","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Noor first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Noor</strong>","goto_screen_id":"hs1-507-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hs1-507","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hs1-507"},{"section":"5 · Hazardous materials & waste","points":0,"objective_ids":[],"type":"content_slide","id":"hs1-507-hint","title":"Noor's hint","layout":"text_media","body_html":"<p><strong>Noor:</strong> “Use one rule for every spill: how much, and how dangerous. Volume is not the only trigger. ⚠ Draft — pending D1.”</p>","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hs1-507","title":"Spill or Code Orange?","section":"5 · Hazardous materials & waste","objective_ids":["hs1-o5"],"points":15,"intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-concern}}<span>Noor · Safety liaison</span></div><p>Three spills, three decisions. Use the rule you'd follow on shift. ⚠ Draft — pending D1</p>","start_node_id":"n1","pass_score":3,"nodes":[{"id":"n1","prompt_html":"<p>A 200 mL bottle of alcohol hand rub falls and leaks in the corridor.</p>","choices":[{"id":"a","text_html":"Call the cleaning supervisor and warn people nearby.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> It is below the Code Orange threshold and not highly toxic. Keep people away until it is cleaned. Draft rule: 500 mL or more, or any highly toxic, reactive or explosive substance. ⚠ Draft — pending D1</p>"},{"id":"b","text_html":"Announce Code Orange.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Not needed here. Code Orange is for spills at or above the threshold (draft: 500 mL), or highly toxic, reactive or explosive substances. ⚠ Draft — pending D1</p>"}]},{"id":"n2","prompt_html":"<p>A full 1-litre bottle of surface disinfectant splits and spreads across the treatment-room floor. (Over the draft threshold. ⚠ Draft — pending D1)</p>","choices":[{"id":"a","text_html":"Announce Code Orange.","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> The spill is over the threshold, so it needs the Code Orange response. ⚠ Draft — pending D1</p>"},{"id":"b","text_html":"Mop it up yourself with paper towels.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>A spill this size needs Code Orange and the right spill kit and PPE, not paper towels. ⚠ Draft — pending D1</p>"}]},{"id":"n3","prompt_html":"<p>A few millilitres of a highly toxic reagent spill on a lab bench.</p>","choices":[{"id":"a","text_html":"Announce Code Orange.","score_delta":1,"goto_node_id":"n4","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Volume does not matter for a highly toxic substance: any amount is Code Orange. ⚠ Draft — pending D1</p>"},{"id":"b","text_html":"Call the cleaning supervisor — it is only a few mL.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Small volume, but highly toxic. Any highly toxic, reactive or explosive substance is Code Orange. ⚠ Draft — pending D1</p>"}]},{"id":"n4","prompt_html":"<p>Code Orange is called. Which order do you follow?</p>","choices":[{"id":"a","text_html":"Isolate and warn → PPE per SDS → contain with the right kit → report.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Protect people first, protect yourself, then contain with the chemical or biological kit, and report to your supervisor and Safety Services.</p>"},{"id":"b","text_html":"Contain with the kit → PPE per SDS → isolate and warn → report.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Containing before isolating and protecting yourself puts you and others at risk. Isolate and warn first.</p>"},{"id":"c","text_html":"Report → isolate and warn → contain → PPE per SDS.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>PPE must go on before you touch the spill, and people nearby need warning first. Report at the end.</p>"}]}],"feedback":{"correct_html":"<p>You applied the Code Orange rule and the four response steps. ⚠ Draft — pending D1</p>","incorrect_html":"<p>Review the rule: 500 mL or more, or any highly toxic, reactive or explosive substance (draft). Then isolate, PPE, contain, report. ⚠ Draft — pending D1</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"drag_drop","id":"hs1-508","title":"Waste segregation","section":"5 · Hazardous materials & waste","objective_ids":["hs1-o5"],"points":10,"prompt_html":"<p>Drag each item to the right waste stream. Bin colours vary by facility: follow the labelled bins in your department. ⚠ Draft — pending 01/B7</p>","items":[{"id":"needle","text_html":"Used needle","correct_target_id":"sharps"},{"id":"dressing","text_html":"Blood-soaked dressing","correct_target_id":"infectious"},{"id":"towel","text_html":"Paper towel (clean)","correct_target_id":"general"},{"id":"blade","text_html":"Scalpel blade","correct_target_id":"sharps"},{"id":"gloves","text_html":"Gloves with body fluid","correct_target_id":"infectious"},{"id":"wrapper","text_html":"Food wrapper","correct_target_id":"general"}],"targets":[{"id":"general","label_html":"General waste — bin colour ⚠ Draft — pending 01/B7"},{"id":"infectious","label_html":"Infectious / biohazard — labelled biohazard bag ⚠ Draft — pending 01/B7"},{"id":"sharps","label_html":"Sharps — rigid, puncture-resistant container"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Sharps go straight into the sharps container. <strong>Never recap.</strong></p>","incorrect_html":"<p>Not quite. Anything sharp goes in the sharps container; anything with body fluid is infectious; clean everyday trash is general. Never recap a needle.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"tabs","id":"hs1-601","title":"Security rules","section":"6 · Security","objective_ids":[],"points":0,"prompt_html":"<p>Security rules for people and premises.</p>","tabs":[{"label":"People","body_html":"<ul><li><strong>ID always</strong> — wear your facility ID at all times.</li><li><strong>Contractor permits</strong> — a valid, approved work permit before any work starts.</li><li><strong>Visitor badges</strong> — visitors sign in at reception. Report anyone in a restricted area without one.</li></ul>"},{"label":"Premises","body_html":"<ul><li><strong>CCTV</strong> covers public areas, entrances and parking.</li><li><strong>Lost and found</strong> — hand found items to Security.</li><li><strong>Designated parking</strong> only.</li><li><strong>No smoking anywhere</strong>, including entrances and parking.</li></ul>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hs1-602","title":"The visitor without a badge","section":"6 · Security","objective_ids":["hs1-o6"],"points":5,"prompt_html":"<p>A man without a badge is in the staff-only medication room. He says he is a contractor. What is the best action?</p>","options":[{"id":"a","text_html":"Politely ask for his work permit and badge; if he has none, call Security and stay with him.","correct":true,"feedback_html":"<p>Correct. Contractors need an approved permit and ID. Calling Security without leaving him alone protects the medicines.</p>"},{"id":"b","text_html":"Accept his word and carry on with your work.","correct":false,"feedback_html":"<p>Risky. Anyone can say they are a contractor; without a permit and badge he should not be in a restricted area.</p>"},{"id":"c","text_html":"Leave the room and go to find Security.","correct":false,"feedback_html":"<p>That leaves him alone with the medicines. Call Security from where you are and stay with him.</p>"},{"id":"d","text_html":"Tell him to leave and say nothing more about it.","correct":false,"feedback_html":"<p>An unbadged person in a restricted area must be reported. Security needs to know, even if he leaves.</p>"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Everyone without ID in a restricted area is your concern.</p>","incorrect_html":"<p>Not quite. Check for a permit and badge, call Security if there is none, and do not leave him alone.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"hotspot","id":"hs1-701","title":"Utility walk-around","section":"7 · Utilities","objective_ids":[],"points":0,"prompt_html":"<p>Walk around the treatment room. Open every item.</p>","image_asset_id":"hs1-img-treatment-room","image_alt":"Treatment room showing sockets, a monitor, an extension lead, a water shut-off valve and an air vent.","mode":"explore","require_all":true,"regions":[{"id":"redsocket","shape":"rect","coords":[676,326,92,92],"label_html":"<strong>Emergency socket (red) ⚠ Draft — pending 01/B6</strong>","feedback_html":"<p>Backed by generator power. Plug critical equipment in here. Generators take over within seconds of an outage. ⚠ Draft — pending 01/B6</p>"},{"id":"stdsocket","shape":"rect","coords":[776,426,86,86],"label_html":"<strong>Standard socket</strong>","feedback_html":"<p>Not backed by the generator. Know which outlets in your area are which.</p>"},{"id":"ups","shape":"rect","coords":[948,268,312,232],"label_html":"<strong>UPS-backed monitor</strong>","feedback_html":"<p>The Uninterruptible Power Supply keeps critical equipment running instantly during a power cut.</p>"},{"id":"extension","shape":"rect","coords":[686,540,236,250],"label_html":"<strong>Unauthorised extension</strong>","feedback_html":"<p>A fire risk and prohibited. Remove it from use and report it; use authorised extensions only.</p>"},{"id":"valve","shape":"rect","coords":[952,592,162,130],"label_html":"<strong>Water shut-off valve</strong>","feedback_html":"<p>Know where your manual shut-off valves are, so you can act fast on a leak. Report problems to Maintenance.</p>"},{"id":"vent","shape":"rect","coords":[1158,568,198,198],"label_html":"<strong>HVAC vent (isolation room)</strong>","feedback_html":"<p>Keeps air pressure and infection-control zones working. Never disable or cover isolation-room vents.</p>"}],"feedback":{"correct_html":"<p>You checked every utility point. Know which sockets are on generator power and where your shut-off valves are.</p>","incorrect_html":"<p>Open every item before you continue: each one tells you what to do in an outage or leak.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hs1-702","title":"The cold isolation room","section":"7 · Utilities","objective_ids":["hs1-o7"],"points":5,"prompt_html":"<p>The isolation room is cold. A visitor asks you to close the air vent. What do you do?</p>","options":[{"id":"a","text_html":"Leave the vent open and report the temperature to Maintenance.","correct":true,"feedback_html":"<p>Correct. Isolation-room vents keep the air pressure that contains infection. Maintenance can fix the temperature safely.</p>"},{"id":"b","text_html":"Close the vent for a short time until the room warms up.","correct":false,"feedback_html":"<p>Even briefly, closing the vent breaks the infection-control zone. Never disable isolation-room vents.</p>"},{"id":"c","text_html":"Tape a cover over the vent to reduce the draught.","correct":false,"feedback_html":"<p>Covering the vent disables it. Report the problem instead.</p>"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Never disable vents in isolation rooms; report to Maintenance.</p>","incorrect_html":"<p>Not quite. HVAC in isolation rooms protects everyone. Keep vents open and report the problem to Maintenance.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hs1-801","title":"Labels, PPM and tagging","section":"8 · Medical equipment","objective_ids":[],"points":0,"blocks":[{"html":"<h4>Inspection label</h4><p>Shows the last inspection date and status. Never use equipment past its due date.</p>"},{"html":"<h4>PPM schedule</h4><p>Biomedical Engineering services equipment on a fixed schedule. Report anything overdue or missing its label.</p>"},{"html":"<h4>“Out of Service” tag</h4><p>Faulty equipment is tagged and removed from use at once. Never attempt your own repair, and never relocate equipment without Biomedical Engineering.</p>"}]},{"section":"8 · Medical equipment","points":0,"objective_ids":[],"type":"branching","id":"hs1-802-ask","title":"The overdue infusion pump","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Dr. Omar first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Dr. Omar</strong>","goto_screen_id":"hs1-802-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hs1-802","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hs1-802"},{"section":"8 · Medical equipment","points":0,"objective_ids":[],"type":"content_slide","id":"hs1-802-hint","title":"Dr. Omar's hint","layout":"text_media","body_html":"<p><strong>Dr. Omar:</strong> “An overdue inspection means nobody can vouch for this device today. Who owns medical equipment checks here?”</p>","media_asset_id":"char-omar-explaining","media_alt":"Dr. Omar, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hs1-802","title":"The overdue infusion pump","section":"8 · Medical equipment","objective_ids":["hs1-o8"],"points":15,"intro_html":"<div class=\"mc-host omar\">{{asset:char-omar-avatar-neutral}}<span>Dr. Omar · Family physician</span></div><p>A busy ward. You are about to set up an infusion pump. Its inspection label is two months overdue.</p>","start_node_id":"n1","pass_score":3,"nodes":[{"id":"n1","image_asset_id":"hs1-img-pump-label","image_alt":"Infusion pump with an overdue inspection label.","prompt_html":"<p>Inspection due: <strong>March</strong>. Today: <strong>May</strong> (fictional training dates). Do you use the pump?</p>","choices":[{"id":"a","text_html":"No — stop and do not use it.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> A pump past its inspection date is not known to be safe today.</p>"},{"id":"b","text_html":"Yes — it seems to work, and the ward is busy.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Working is not the same as safe. Never use equipment past its due date.</p>"}]},{"id":"n2","prompt_html":"<p>What do you do with the pump?</p>","choices":[{"id":"a","text_html":"Tag it “Out of Service” and remove it from use.","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> The tag stops a colleague from using it by mistake.</p>"},{"id":"b","text_html":"Put it back in the store room for someone else to deal with.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Untagged, the next person may use it. Tag it out of service.</p>"},{"id":"c","text_html":"Open it and check it yourself.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Never attempt your own repair or bypass a fault. That is Biomedical Engineering's job.</p>"}]},{"id":"n3","prompt_html":"<p>Who do you notify?</p>","choices":[{"id":"a","text_html":"Biomedical Engineering.","score_delta":1,"goto_node_id":"n4","feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Biomedical Engineering runs the PPM programme and will inspect it.</p>"},{"id":"b","text_html":"The supplier's sales representative.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Inspection and PPM are coordinated by Biomedical Engineering. Report to them.</p>"},{"id":"c","text_html":"IT support.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>IT handles network outages, not medical equipment. Notify Biomedical Engineering.</p>"}]},{"id":"n4","prompt_html":"<p>A colleague says: “Just take the pump from Room 5, nobody's using it.” What do you do?</p>","choices":[{"id":"a","text_html":"Don't move it yourself; ask Biomedical Engineering to arrange a replacement.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for the clinic.</strong></p><p><strong>Correct.</strong> Each location is assessed for the equipment placed there. Never relocate equipment without Biomedical Engineering, even temporarily.</p>"},{"id":"b","text_html":"Move the pump from Room 5 — it's only for today.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for the clinic.</strong></p><p>Even a temporary move bypasses the location assessment. Coordinate with Biomedical Engineering first.</p>"}]}],"feedback":{"correct_html":"<p>Spot it, report it: you stopped, tagged, notified Biomedical Engineering and did not relocate equipment.</p>","incorrect_html":"<p>Review labels, tagging and the never-relocate rule, then try again.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"true_false","id":"hs1-803","title":"Oxygen cylinders","section":"8 · Medical equipment","objective_ids":["hs1-o8"],"points":5,"prompt_html":"<p>True or false? <strong>Store oxygen cylinders upright and secured, with full and empty clearly separated.</strong></p>","correct":true,"feedback":{"correct_html":"<p><strong>Correct — true.</strong> Secure them with a chain or stand, separate full from empty, and keep them away from flames, sparks and smoking.</p>","incorrect_html":"<p>It is true. An unsecured cylinder can fall and be damaged, and mixing full with empty causes mistakes in an emergency.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"tabs","id":"hs1-901","title":"Ionising vs non-ionising","section":"9 · Radiation & laser","objective_ids":[],"points":0,"prompt_html":"<p>Radiation is energy travelling as waves or particles.</p>","tabs":[{"label":"Ionising","body_html":"<p>X-ray, CT. Enough energy to remove electrons from atoms: needs <strong>dosimeters, shielding</strong> and dose tracking.</p>"},{"label":"Non-ionising","body_html":"<p>MRI, ultrasound, laser light. Lower energy, but still needs its own precautions.</p>"},{"label":"MRI","body_html":"<p>The <strong>magnet is always on</strong>. No metal objects, oxygen cylinders or unscreened staff. Screening every time.</p>"},{"label":"X-ray rooms","body_html":"<p>Wear a <strong>lead apron</strong> during exposure. Stand behind the shield or leave the room.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"matching","id":"hs1-902","title":"Protection principles","section":"9 · Radiation & laser","objective_ids":["hs1-o9"],"points":5,"prompt_html":"<p>Match each radiation protection principle to its meaning.</p>","pairs":[{"id":"just","left_html":"Justification","right_html":"The benefit must clearly justify the radiation risk."},{"id":"opt","left_html":"Optimisation","right_html":"Keep exposure as low as reasonably achievable (ALARA)."},{"id":"lim","left_html":"Limitation","right_html":"A firm upper dose limit applies to every worker and the public."}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Justify the exposure, optimise it, and never exceed the limit.</p>","incorrect_html":"<p>Not quite. Justification asks “is it worth it?”, optimisation asks “is it as low as possible?”, limitation sets the ceiling.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"labeled_diagram","id":"hs1-903","title":"ALARA","section":"9 · Radiation & laser","objective_ids":[],"points":0,"prompt_html":"<p>ALARA: As Low As Reasonably Achievable. Three levers you control.</p>","image_asset_id":"hs1-img-alara","image_alt":"ALARA: time, distance and shielding around a radiation source.","mode":"display","labels":[{"id":"time","text":"Time — less time near the source, less dose","x":500,"y":140},{"id":"distance","text":"Distance — step back; intensity drops sharply","x":780,"y":800},{"id":"shield","text":"Shielding — aprons, barriers and walls absorb it","x":220,"y":800}],"feedback":{"correct_html":"<p>Less time, more distance, the right shielding: three levers that lower your dose.</p>","incorrect_html":"<p>Read each lever: time, distance and shielding all reduce exposure.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hs1-904","title":"Staying accountable","section":"9 · Radiation & laser","objective_ids":[],"points":0,"prompt_html":"<p>Staying accountable near radiation.</p>","items":[{"title":"OSL dosimeter","body_html":"<p>Wear your Optically Stimulated Luminescence badge at all times in or near radiation areas.</p>"},{"title":"Lead apron","body_html":"<p>Required whenever you are in the room during exposure, even for a quick scan.</p>"},{"title":"RSO is your contact","body_html":"<p>The Radiation Safety Officer oversees compliance and dose records. Ask them about any radiation-safety concern.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hs1-905","title":"Dose bands","section":"9 · Radiation & laser","objective_ids":["hs1-o9"],"points":5,"prompt_html":"<p>Your quarterly OSL reading shows <strong>2.0 mSv</strong>. What happens? <em>⚠ Draft — pending 01/B4</em></p>","options":[{"id":"a","text_html":"Notification level: you are informed and placed under monitoring.","correct":true,"feedback_html":"<p>Correct for the draft bands: 2.0 mSv is between 1.25 and 3.75 mSv. ⚠ Draft — pending 01/B4</p>"},{"id":"b","text_html":"Reading level: no action needed.","correct":false,"feedback_html":"<p>The reading level ends at 1.25 mSv; 2.0 mSv is above it. ⚠ Draft — pending 01/B4</p>"},{"id":"c","text_html":"Investigation level: an over-exposure investigation starts.","correct":false,"feedback_html":"<p>Investigation starts above 3.75 mSv; 2.0 mSv is below that. ⚠ Draft — pending 01/B4</p>"}],"feedback":{"correct_html":"<p><strong>Correct.</strong></p><table><tr><th>Level</th><th>Quarterly reading</th><th>Action</th></tr><tr><td>Reading</td><td>up to 1.25 mSv</td><td>No action</td></tr><tr><td>Notification</td><td>1.25–3.75 mSv</td><td>You are informed and monitored</td></tr><tr><td>Investigation</td><td>above 3.75 mSv</td><td>Over-exposure investigation policy</td></tr></table><p>Draft values from the source; limits and bands ⚠ Draft — pending 01/B4.</p>","incorrect_html":"<p>Not quite. Check where 2.0 mSv falls:</p><table><tr><th>Level</th><th>Quarterly reading</th><th>Action</th></tr><tr><td>Reading</td><td>up to 1.25 mSv</td><td>No action</td></tr><tr><td>Notification</td><td>1.25–3.75 mSv</td><td>You are informed and monitored</td></tr><tr><td>Investigation</td><td>above 3.75 mSv</td><td>Over-exposure investigation policy</td></tr></table><p>Draft values from the source; limits and bands ⚠ Draft — pending 01/B4.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"matching","id":"hs1-906","title":"Laser classes","section":"9 · Radiation & laser","objective_ids":["hs1-o9"],"points":5,"prompt_html":"<p>Match each laser class to its hazard. Higher class, greater hazard. Class wording ⚠ Draft — pending 01/B5.</p>","pairs":[{"id":"c1","left_html":"Class 1 / 1M","right_html":"Safe under normal use"},{"id":"c2","left_html":"Class 2 / 2M","right_html":"Low power — the blink reflex gives some protection"},{"id":"c3r","left_html":"Class 3R","right_html":"Low risk if safety precautions are followed"},{"id":"c3b","left_html":"Class 3B","right_html":"Hazardous — direct and reflected viewing"},{"id":"c4","left_html":"Class 4","right_html":"Severe hazard — eyes, skin and fire"}],"feedback":{"correct_html":"<p><strong>Correct.</strong> Check the class label before working near any laser. ⚠ Draft — pending 01/B5</p>","incorrect_html":"<p>Not quite. The hazard rises with the class: 1 safe, 2 blink reflex, 3R low risk with precautions, 3B direct and reflected viewing, 4 severe. ⚠ Draft — pending 01/B5</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hs1-907","title":"Laser hazards and measures","section":"9 · Radiation & laser","objective_ids":[],"points":0,"blocks":[{"html":"<h4>Hazards</h4><ul><li>Eyes — permanent damage, often with no pain at first</li><li>Skin — burns from direct or reflected beams</li><li>High voltage inside the equipment</li></ul>"},{"html":"<h4>Measures</h4><ul><li>Eye protection</li><li>Beam management</li><li>Control reflections</li><li>Training</li></ul>"}]},{"type":"game","id":"hs1-950","title":"One shift, three plans","section":"Capstone & completion","objective_ids":["hs1-o10"],"points":25,"template":"case_sim","intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-neutral}}<span>Noor · Safety liaison</span></div><p>One afternoon shift. Three things go wrong. Your decisions decide how it ends. No timer — take your time. You have 3 lives and one hint per situation.</p>","mechanics":{"score":{"id":"score","start":0,"streak_step":1,"max_multiplier":1},"lives":{"id":"lives","start":3},"hints":{"id":"hint","hints":[{"text":"People first, then the hazard. Check the spill rule: volume and toxicity. ⚠ Draft — pending D1","cost":0},{"text":"Smoke means fire: Code Red. In RACE, rescue comes before extinguishing.","cost":0},{"text":"A label past its date means the device is not safe to use today.","cost":0}]}},"start_node_id":"n1","pass_score":2,"nodes":[{"id":"n1","content_html":"<p><strong>1 · 14:10.</strong> In a busy clinic, a cleaner knocks over a large 1-litre bottle of surface disinfectant. It spreads towards an oxygen cylinder. ⚠ Draft — pending D1</p>","choices":[{"id":"a","text_html":"Isolate the area, warn people, move the oxygen cylinder away and announce Code Orange.","to":"n2","feedback_html":"<p><strong>Right.</strong> Over the draft threshold, so Code Orange; and oxygen must be kept away from hazards. ⚠ Draft — pending D1</p>","on_choose":[{"do":"score.correct","points":1}]},{"id":"b","text_html":"Grab paper towels and mop it up yourself.","to":"n2","feedback_html":"<p>A spill this size needs Code Orange, the right kit and PPE per the SDS. You lost a life. ⚠ Draft — pending D1</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]},{"id":"c","text_html":"Leave it to the cleaner and carry on with your patients.","to":"n2","feedback_html":"<p>The hazard and the oxygen cylinder are still next to people. Isolate and warn first. You lost a life.</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]}]},{"id":"n2","content_html":"<p><strong>2 · 15:30.</strong> The alarm sounds. Smoke is coming from the store room, and a patient is waiting in the chair beside the door.</p>","choices":[{"id":"a","text_html":"Code Red: move the patient away first, then raise the alarm and close the door.","to":"n3","feedback_html":"<p><strong>Right.</strong> Smoke means Code Red, and RACE starts with rescue.</p>","on_choose":[{"do":"score.correct","points":1}]},{"id":"b","text_html":"Code Orange: it could be the disinfectant from earlier.","to":"n3","feedback_html":"<p>Smoke means fire: Code Red. The wrong code sends the wrong team. You lost a life.</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]},{"id":"c","text_html":"Go straight in with an extinguisher.","to":"n3","feedback_html":"<p>The patient is still beside the smoke. Rescue comes before extinguishing. You lost a life.</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]}]},{"id":"n3","content_html":"<p><strong>3 · 17:00.</strong> All clear. Dr. Omar needs suction for a patient and you notice the suction unit's inspection label has expired.</p>","choices":[{"id":"a","text_html":"Tag it “Out of Service”, use another approved unit, and notify Biomedical Engineering.","to":"debrief","feedback_html":"<p><strong>Right.</strong> Dr. Omar: “That is the habit we want from every new colleague.”</p>","on_choose":[{"do":"score.correct","points":1}]},{"id":"b","text_html":"Use it — it switched on fine.","to":"debrief","feedback_html":"<p>Working is not the same as safe. Never use equipment past its due date. You lost a life.</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]},{"id":"c","text_html":"Fetch the unit from the next room without telling anyone.","to":"debrief","feedback_html":"<p>Never relocate equipment without Biomedical Engineering, and the expired unit is still untagged. You lost a life.</p>","on_choose":[{"do":"lives.lose","n":1},{"do":"score.wrong"}]}]},{"id":"debrief","content_html":"<h4>Debrief: one shift, three plans</h4><ul><li><strong>The spill</strong> — Hazmat &amp; Waste plan (Code Orange), with Fire Safety (oxygen kept away).</li><li><strong>The smoke</strong> — Fire Safety plan (Code Red, RACE) and Internal Disaster (code activation).</li><li><strong>The suction unit</strong> — Biomedical plan (inspection label, out-of-service tag, Biomedical Engineering).</li></ul>","choices":[{"id":"finish","text_html":"Finish the shift and see your score.","to":null}]}],"feedback":{"correct_html":"<p>You connected three plans in one shift: people first, the right code, and equipment you can trust.</p>","incorrect_html":"<p>Some decisions put people at risk. Review the debrief: Hazmat &amp; Waste (spill), Fire Safety (RACE), Biomedical (labels). Then try again.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}]},{"type":"results_breakdown","id":"hs1-980","title":"Your results","section":"Capstone & completion","objective_ids":[],"points":0,"body_html":"<p>Your results by objective. Pass mark: 80% (176 of 220 points). Revisit any section below 70%.</p>","sections":[{"title":"hs1-o1 · The eight FMS plans","screen_ids":["hs1-104"],"advice_html":"<p>Revisit section <strong>1 · The eight FMS plans</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 1 · The eight FMS plans</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o2 · AREC and hierarchy of controls","screen_ids":["hs1-204","hs1-205"],"advice_html":"<p>Revisit section <strong>2 · Occupational Health & Safety</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 2 · Occupational Health & Safety</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o3 · Emergency codes and response pattern","screen_ids":["hs1-302","hs1-304"],"advice_html":"<p>Revisit section <strong>3 · Emergency codes</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 3 · Emergency codes</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o4 · RACE, PASS, extinguishers and evacuation","screen_ids":["hs1-402","hs1-403","hs1-405","hs1-407","hs1-408","hs1-409"],"advice_html":"<p>Revisit section <strong>4 · Fire safety</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 4 · Fire safety</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o5 · GHS, NFPA, Code Orange and waste","screen_ids":["hs1-502","hs1-503","hs1-504","hs1-507","hs1-508"],"advice_html":"<p>Revisit section <strong>5 · Hazardous materials & waste</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 5 · Hazardous materials & waste</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o6 · Security rules","screen_ids":["hs1-602"],"advice_html":"<p>Revisit section <strong>6 · Security</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 6 · Security</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o7 · Utilities","screen_ids":["hs1-702"],"advice_html":"<p>Revisit section <strong>7 · Utilities</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 7 · Utilities</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o8 · Medical equipment","screen_ids":["hs1-802","hs1-803"],"advice_html":"<p>Revisit section <strong>8 · Medical equipment</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 8 · Medical equipment</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o9 · Radiation and laser","screen_ids":["hs1-902","hs1-905","hs1-906"],"advice_html":"<p>Revisit section <strong>9 · Radiation & laser</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 9 · Radiation & laser</strong> from the menu (☰) to revisit it.</p>"},{"title":"hs1-o10 · Capstone","screen_ids":["hs1-950"],"advice_html":"<p>Revisit section <strong>Capstone & completion</strong> from the menu, then try its questions again.</p><p><strong>Open Mission 3 · Emergency codes and Mission 4 · Fire safety</strong> from the menu (☰) to revisit it.</p>"}],"weak_threshold":70,"show_total":true},{"type":"poll","id":"hs1-981","title":"How confident are you now?","section":"Capstone & completion","objective_ids":[],"points":0,"prompt_html":"<p>How confident are you to act in a fire right now?</p>","options":[{"id":"c1","text_html":"1 — Not confident yet"},{"id":"c2","text_html":"2 — A little confident"},{"id":"c3","text_html":"3 — Fairly confident"},{"id":"c4","text_html":"4 — Very confident"}],"multi":false,"allow_text":false,"reflection_html":"<p>Not scored. Compare this with your answer at the start of the course.</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"summary","id":"hs1-990","title":"Your completion actions","section":"Capstone & completion","objective_ids":[],"points":0,"body_html":"<p>Finish these this week:</p><ul><li>✔ Locate your evacuation route and assembly point</li><li>✔ Save emergency numbers to your phone</li><li>✔ Find your nearest eyewash</li><li>✔ Ask your supervisor who your Safety Liaison is</li><li>✔ Sign the acknowledgement ⚠ Draft — pending D14</li></ul><p><strong>Contact:</strong> your Safety &amp; Security Manager.</p><p class=\"mc-role-line\"><strong>As a {{role_label}}:</strong> start with the first item on this list in your own area this week.</p><p class=\"mc-xp-final\"><strong>You finished with {{xp}} XP.</strong> Your rank is at the top of the screen.</p>","show_score":true,"show_completion":true}]};
